import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import 'package:vesta_app/theme/vesta_theme.dart';

import 'package:vesta_app/l10n/tr.dart';
/// Latest weekly summary generated by the server (Sunday afternoons).
class WeeklySummaryCard extends StatelessWidget {
  final String childId;

  const WeeklySummaryCard({super.key, required this.childId});

  static String _hours(num ms) {
    final minutes = (ms / 60000).round();
    if (minutes < 60) return '$minutes min';
    final h = minutes ~/ 60;
    final m = minutes % 60;
    return m == 0 ? '$h h' : tr('{0} h {1} min', [h, m]);
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('children')
          .doc(childId)
          .collection('weekly_summaries')
          .orderBy('weekId', descending: true)
          .limit(1)
          .snapshots(),
      builder: (context, snapshot) {
        final doc = snapshot.data?.docs.firstOrNull;
        if (doc == null) return const SizedBox.shrink();

        final data = doc.data();
        final alerts = (data['alerts'] as Map?) ?? {};
        final byType = (alerts['byType'] as Map?) ?? {};
        final usage = data['usage'] as Map?;
        final topApps = (usage?['topApps'] as List?)?.whereType<Map>().toList() ?? [];

        Widget stat(String value, String label) => Expanded(
              child: Column(
                children: [
                  Text(
                    value,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 20,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  Text(
                    label,
                    textAlign: TextAlign.center,
                    style: const TextStyle(color: Colors.white, fontSize: 12),
                  ),
                ],
              ),
            );

        return Container(
          margin: const EdgeInsets.only(bottom: 16),
          padding: const EdgeInsets.all(18),
          decoration: BoxDecoration(
            gradient: VestaTheme.primaryGradient,
            borderRadius: BorderRadius.circular(22),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Icon(Icons.insights_rounded, color: Colors.white),
                  SizedBox(width: 8),
                  Text(
                    tr('Resumen de la semana'),
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ],
              ),
              Text(
                tr('Semana del {0}', [data['weekId']]),
                style: const TextStyle(color: Colors.white, fontSize: 12),
              ),
              const SizedBox(height: 14),
              Row(
                children: [
                  if (usage != null && (usage['daysWithData'] ?? 0) > 0)
                    stat(_hours(usage['averageDailyMs'] ?? 0), tr('pantalla al día')),
                  stat('${alerts['total'] ?? 0}', 'alertas'),
                  stat('${byType['critical'] ?? 0}', tr('críticas')),
                ],
              ),
              if (topApps.isNotEmpty) ...[
                const SizedBox(height: 14),
                Text(
                  tr('Apps más usadas'),
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 4),
                for (final app in topApps.take(3))
                  Text(
                    '• ${app['appName']} · ${_hours(app['ms'] ?? 0)}',
                    style: const TextStyle(color: Colors.white, fontSize: 13),
                  ),
              ],
            ],
          ),
        );
      },
    );
  }
}
